script:
const loadingElement = root_element.querySelector(
	".company-policy-loading"
);

const messageElement = root_element.querySelector(
	".company-policy-message"
);

const contentElement = root_element.querySelector(
	".company-policy-content"
);

const companyElement = root_element.querySelector(
	".company-policy-company"
);


function showMessage(message) {
	loadingElement.style.display = "none";
	contentElement.style.display = "none";

	messageElement.textContent = message;
	messageElement.style.display = "block";
}


function showPolicy(company, policy) {
	loadingElement.style.display = "none";
	messageElement.style.display = "none";

	companyElement.textContent = company || "";

	contentElement.innerHTML =
		policy || "<p>No policy content is available.</p>";

	contentElement.style.display = "block";
}


function getCompanyPolicy(company) {
	frappe.call({
		method: "frappe.client.get_value",
		args: {
			doctype: "Company Policy",
			filters: {
				company: company
			},
			fieldname: [
				"name",
				"policys"
			]
		},
		callback(response) {
			const policyData = response.message;

			if (!policyData) {
				showMessage(
					`No company policy was found for ${company}.`
				);
				return;
			}

			showPolicy(
				company,
				policyData.policys
			);
		},
		error(error) {
			console.error(
				"Error fetching Company Policy:",
				error
			);

			showMessage(
				"Unable to load the company policy."
			);
		}
	});
}


function getLoggedInEmployee() {
	if (
		!frappe.session.user ||
		frappe.session.user === "Guest"
	) {
		showMessage(
			"Please log in to view the company policy."
		);
		return;
	}

	frappe.call({
		method: "frappe.client.get_value",
		args: {
			doctype: "Employee",
			filters: {
				user_id: frappe.session.user,
				status: "Active"
			},
			fieldname: [
				"name",
				"employee_name",
				"company"
			]
		},
		callback(response) {
			const employee = response.message;

			if (!employee) {
				showMessage(
					"No active Employee is linked to your user account."
				);
				return;
			}

			if (!employee.company) {
				showMessage(
					"No company is set in your Employee record."
				);
				return;
			}

			getCompanyPolicy(employee.company);
		},
		error(error) {
			console.error(
				"Error fetching Employee:",
				error
			);

			showMessage(
				"Unable to find the Employee linked to your user account."
			);
		}
	});
}


getLoggedInEmployee();

style:
.company-policy-wrapper {
	position: relative;
	overflow: hidden;
	min-height: 220px;
	padding: 26px;
	border: 1px solid var(--border-color);
	border-radius: 16px;

	background:
		linear-gradient(
			135deg,
			rgba(37, 99, 235, 0.08),
			transparent 42%
		),
		var(--card-bg);

	box-shadow:
		0 10px 30px rgba(15, 23, 42, 0.08),
		0 2px 8px rgba(15, 23, 42, 0.04);

	transition:
		transform 0.25s ease,
		box-shadow 0.25s ease,
		border-color 0.25s ease;
}

.company-policy-wrapper::before {
	content: "";
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	height: 4px;
	background: linear-gradient(
		90deg,
		#2563eb,
		#4f46e5,
		#7c3aed
	);
}

.company-policy-wrapper::after {
	content: "";
	position: absolute;
	top: -70px;
	right: -70px;
	width: 180px;
	height: 180px;
	border-radius: 50%;
	background: rgba(37, 99, 235, 0.08);
	pointer-events: none;
}

.company-policy-wrapper:hover {
	transform: translateY(-2px);
	border-color: rgba(37, 99, 235, 0.35);

	box-shadow:
		0 16px 40px rgba(15, 23, 42, 0.12),
		0 4px 12px rgba(15, 23, 42, 0.06);
}


/* Header */

.company-policy-header {
	position: relative;
	z-index: 1;

	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 16px;

	padding-bottom: 18px;
	margin-bottom: 22px;

	border-bottom: 1px solid var(--border-color);
}

.company-policy-title {
	margin: 0;

	font-size: 22px;
	font-weight: 700;
	line-height: 1.3;
	letter-spacing: -0.4px;

	color: var(--text-color);
}

.company-policy-company {
	display: inline-flex;
	align-items: center;

	margin: 7px 0 0;
	padding: 5px 10px;

	border-radius: 20px;
	background: rgba(37, 99, 235, 0.1);

	font-size: 12px;
	font-weight: 600;
	line-height: 1.4;

	color: #2563eb;
}


/* Icon */

.company-policy-icon {
	position: relative;
	z-index: 1;

	display: flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;

	width: 52px;
	height: 52px;

	border-radius: 14px;

	background: linear-gradient(
		135deg,
		#2563eb,
		#4f46e5
	);

	box-shadow:
		0 8px 18px rgba(37, 99, 235, 0.25),
		inset 0 1px 0 rgba(255, 255, 255, 0.25);

	font-size: 22px;
	color: #ffffff;

	transition:
		transform 0.25s ease,
		box-shadow 0.25s ease;
}

.company-policy-wrapper:hover .company-policy-icon {
	transform: scale(1.05) rotate(-2deg);

	box-shadow:
		0 12px 24px rgba(37, 99, 235, 0.32),
		inset 0 1px 0 rgba(255, 255, 255, 0.25);
}


/* Loading */

.company-policy-loading {
	position: relative;
	z-index: 1;

	display: flex;
	align-items: center;
	justify-content: center;
	gap: 10px;

	min-height: 110px;
	padding: 24px;

	border: 1px dashed var(--border-color);
	border-radius: 12px;

	background: var(--control-bg);

	font-size: 14px;
	font-weight: 500;

	color: var(--text-muted);
}

.company-policy-loading i {
	font-size: 18px;
	color: #2563eb;
}


/* Error or empty message */

.company-policy-message {
	position: relative;
	z-index: 1;

	display: none;

	padding: 16px 18px;

	border: 1px solid rgba(245, 158, 11, 0.25);
	border-left: 4px solid #f59e0b;
	border-radius: 10px;

	background: rgba(245, 158, 11, 0.08);

	font-size: 14px;
	font-weight: 500;
	line-height: 1.6;

	color: var(--text-color);
}


/* Policy content */

.company-policy-content {
	position: relative;
	z-index: 1;

	display: none;

	padding: 22px;

	border: 1px solid var(--border-color);
	border-radius: 12px;

	background: rgba(255, 255, 255, 0.35);

	font-size: 14px;
	line-height: 1.8;

	color: var(--text-color);
}

.company-policy-content h1,
.company-policy-content h2,
.company-policy-content h3,
.company-policy-content h4 {
	position: relative;

	margin-top: 24px;
	margin-bottom: 12px;

	font-weight: 700;
	line-height: 1.4;

	color: var(--text-color);
}

.company-policy-content h1:first-child,
.company-policy-content h2:first-child,
.company-policy-content h3:first-child,
.company-policy-content h4:first-child {
	margin-top: 0;
}

.company-policy-content h1 {
	font-size: 22px;
}

.company-policy-content h2 {
	font-size: 19px;
}

.company-policy-content h3 {
	font-size: 16px;
}

.company-policy-content h4 {
	font-size: 14px;
}

.company-policy-content h2::after,
.company-policy-content h3::after {
	content: "";
	display: block;

	width: 42px;
	height: 3px;

	margin-top: 7px;
	border-radius: 10px;

	background: linear-gradient(
		90deg,
		#2563eb,
		#7c3aed
	);
}

.company-policy-content p {
	margin: 0 0 14px;
}

.company-policy-content ul,
.company-policy-content ol {
	margin: 10px 0 16px;
	padding-left: 24px;
}

.company-policy-content li {
	margin-bottom: 8px;
	padding-left: 4px;
}

.company-policy-content li::marker {
	color: #2563eb;
	font-weight: 700;
}

.company-policy-content strong {
	font-weight: 700;
	color: var(--text-color);
}

.company-policy-content a {
	font-weight: 600;
	text-decoration: none;
	color: #2563eb;
}

.company-policy-content a:hover {
	text-decoration: underline;
}

.company-policy-content blockquote {
	margin: 18px 0;
	padding: 14px 18px;

	border-left: 4px solid #2563eb;
	border-radius: 0 10px 10px 0;

	background: rgba(37, 99, 235, 0.07);

	color: var(--text-muted);
}


/* Scrollbar for long policies */

.company-policy-content {
	max-height: 550px;
	overflow-y: auto;
	scrollbar-width: thin;
	scrollbar-color: rgba(37, 99, 235, 0.45) transparent;
}

.company-policy-content::-webkit-scrollbar {
	width: 6px;
}

.company-policy-content::-webkit-scrollbar-track {
	background: transparent;
}

.company-policy-content::-webkit-scrollbar-thumb {
	border-radius: 10px;
	background: rgba(37, 99, 235, 0.4);
}

.company-policy-content::-webkit-scrollbar-thumb:hover {
	background: rgba(37, 99, 235, 0.65);
}


/* Dark mode compatibility */

[data-theme="dark"] .company-policy-content,
[data-theme="dark"] .company-policy-wrapper {
	background-color: var(--card-bg);
}

[data-theme="dark"] .company-policy-content {
	background: rgba(255, 255, 255, 0.03);
}

[data-theme="dark"] .company-policy-company {
	color: #93c5fd;
	background: rgba(59, 130, 246, 0.15);
}


/* Mobile responsive */

@media (max-width: 576px) {
	.company-policy-wrapper {
		padding: 20px;
		border-radius: 14px;
	}

	.company-policy-header {
		align-items: flex-start;
	}

	.company-policy-title {
		font-size: 19px;
	}

	.company-policy-icon {
		width: 46px;
		height: 46px;
		font-size: 19px;
	}

	.company-policy-content {
		max-height: 450px;
		padding: 17px;
		font-size: 13px;
	}
}

script:
const loadingElement = root_element.querySelector(
	".company-events-loading"
);

const messageElement = root_element.querySelector(
	".company-events-message"
);

const eventsListElement = root_element.querySelector(
	".company-events-list"
);

const countElement = root_element.querySelector(
	".event-count-value"
);


function escapeHtml(value) {
	const div = document.createElement("div");
	div.textContent = value || "";
	return div.innerHTML;
}


function formatEventTime(timeValue) {
	if (!timeValue) {
		return "";
	}

	const timeParts = String(timeValue).split(":");

	let hours = parseInt(timeParts[0], 10);
	const minutes = timeParts[1] || "00";

	if (Number.isNaN(hours)) {
		return timeValue;
	}

	const period = hours >= 12 ? "PM" : "AM";

	hours = hours % 12;
	hours = hours || 12;

	return `${hours}:${minutes} ${period}`;
}


function getDateParts(dateValue) {
	const dateParts = String(dateValue).split("-");

	if (dateParts.length !== 3) {
		return {
			day: "",
			month: "",
			year: ""
		};
	}

	const year = dateParts[0];
	const monthNumber = parseInt(dateParts[1], 10);
	const day = dateParts[2];

	const monthNames = [
		"Jan",
		"Feb",
		"Mar",
		"Apr",
		"May",
		"Jun",
		"Jul",
		"Aug",
		"Sep",
		"Oct",
		"Nov",
		"Dec"
	];

	return {
		day,
		month: monthNames[monthNumber - 1] || "",
		year
	};
}


function getDaysRemaining(eventDate) {
	const today = frappe.datetime.get_today();

	return frappe.datetime.get_day_diff(
		eventDate,
		today
	);
}


function getEventStatus(eventDate) {
	const daysRemaining = getDaysRemaining(eventDate);

	if (daysRemaining === 0) {
		return {
			label: "Today",
			className: "event-status-today",
			message: "Happening today"
		};
	}

	if (daysRemaining === 1) {
		return {
			label: "Tomorrow",
			className: "event-status-tomorrow",
			message: "Starts tomorrow"
		};
	}

	return {
		label: "Upcoming",
		className: "event-status-upcoming",
		message: `In ${daysRemaining} days`
	};
}


function showMessage(message) {
	loadingElement.style.display = "none";
	eventsListElement.style.display = "none";

	messageElement.innerHTML = `
		<div class="events-empty-state">
			<div class="events-empty-icon">
				<i class="fa fa-calendar-times-o"></i>
			</div>

			<h4>No Upcoming Events</h4>

			<p>${escapeHtml(message)}</p>
		</div>
	`;

	messageElement.style.display = "block";
	countElement.textContent = "0";
}


function createEventCard(event, index) {
	const dateParts = getDateParts(event.event_date);
	const formattedTime = formatEventTime(event.time);
	const status = getEventStatus(event.event_date);

	const eventDescription = event.description
		? event.description
		: `
			<p class="event-description-empty">
				No description has been provided for this event.
			</p>
		`;

	const todayClass =
		getDaysRemaining(event.event_date) === 0
			? "company-event-today"
			: "";

	return `
		<div class="company-event-card ${todayClass}">
			<div class="company-event-number">
				${String(index + 1).padStart(2, "0")}
			</div>

			<div class="company-event-date-box">
				<span class="company-event-month">
					${escapeHtml(dateParts.month)}
				</span>

				<span class="company-event-day">
					${escapeHtml(dateParts.day)}
				</span>

				<span class="company-event-year">
					${escapeHtml(dateParts.year)}
				</span>
			</div>

			<div class="company-event-details">
				<div class="company-event-title-row">
					<h4 class="company-event-title">
						${escapeHtml(
							event.event_name || "Company Event"
						)}
					</h4>

					<span class="company-event-status ${status.className}">
						${escapeHtml(status.label)}
					</span>
				</div>

				<div class="company-event-meta">
					<div class="company-event-meta-item">
						<i class="fa fa-calendar-o"></i>

						<span>
							${escapeHtml(
								frappe.datetime.str_to_user(
									event.event_date
								)
							)}
						</span>
					</div>

					${
						formattedTime
							? `
								<div class="company-event-meta-item">
									<i class="fa fa-clock-o"></i>

									<span>
										${escapeHtml(formattedTime)}
									</span>
								</div>
							`
							: ""
					}

					<div class="company-event-meta-item event-days-left">
						<i class="fa fa-hourglass-half"></i>

						<span>
							${escapeHtml(status.message)}
						</span>
					</div>
				</div>

				<div class="company-event-description">
					${eventDescription}
				</div>
			</div>
		</div>
	`;
}


function renderEvents(events) {
	loadingElement.style.display = "none";
	messageElement.style.display = "none";

	if (!events || !events.length) {
		showMessage(
			"There are currently no scheduled company events."
		);
		return;
	}

	countElement.textContent = events.length;

	eventsListElement.innerHTML = events
		.map((event, index) => {
			return createEventCard(event, index);
		})
		.join("");

	eventsListElement.style.display = "block";
}


function loadCompanyEvents() {
	const today = frappe.datetime.get_today();

	frappe.call({
		method: "frappe.client.get_list",
		args: {
			doctype: "Company Event",

			fields: [
				"name",
				"event_name",
				"event_date",
				"time",
				"description"
			],

			filters: [
				["event_date", ">=", today]
			],

			order_by: "event_date asc, time asc",

			limit_page_length: 20
		},

		callback(response) {
			const events = response.message || [];

			renderEvents(events);
		},

		error(error) {
			console.error(
				"Error loading Company Events:",
				error
			);

			showMessage(
				"Unable to load company events. Please try again."
			);
		}
	});
}


loadCompanyEvents();

style:
.company-events-list {
	position: relative;
	z-index: 1;
	display: none;
	max-height: 580px;
	padding: 4px 6px 4px 2px;
	overflow-y: auto;
}

.company-event-card {
	position: relative;
	display: grid;
	grid-template-columns: 34px 82px minmax(0, 1fr);
	align-items: stretch;
	gap: 16px;

	margin-bottom: 16px;
	padding: 18px;

	overflow: hidden;

	border: 1px solid var(--border-color);
	border-radius: 16px;

	background:
		linear-gradient(
			135deg,
			rgba(79, 70, 229, 0.035),
			transparent 55%
		),
		var(--card-bg);

	box-shadow:
		0 5px 18px rgba(15, 23, 42, 0.06),
		0 1px 3px rgba(15, 23, 42, 0.04);

	transition:
		transform 0.22s ease,
		box-shadow 0.22s ease,
		border-color 0.22s ease;
}

.company-event-card::before {
	content: "";
	position: absolute;
	top: 0;
	left: 0;
	width: 5px;
	height: 100%;

	background: linear-gradient(
		180deg,
		#2563eb,
		#4f46e5,
		#7c3aed
	);
}

.company-event-card:last-child {
	margin-bottom: 0;
}

.company-event-card:hover {
	transform: translateY(-3px);
	border-color: rgba(79, 70, 229, 0.35);

	box-shadow:
		0 14px 30px rgba(15, 23, 42, 0.11),
		0 3px 8px rgba(15, 23, 42, 0.05);
}

.company-event-today {
	border-color: rgba(22, 163, 74, 0.35);

	background:
		linear-gradient(
			135deg,
			rgba(22, 163, 74, 0.08),
			transparent 55%
		),
		var(--card-bg);
}

.company-event-today::before {
	background: linear-gradient(
		180deg,
		#16a34a,
		#22c55e
	);
}


/* Event number */

.company-event-number {
	display: flex;
	align-items: center;
	justify-content: center;

	font-size: 11px;
	font-weight: 800;
	letter-spacing: 0.5px;

	color: var(--text-muted);
}


/* Date section */

.company-event-date-box {
	position: relative;

	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;

	min-height: 94px;
	padding: 11px 8px;

	overflow: hidden;

	border: 1px solid rgba(79, 70, 229, 0.14);
	border-radius: 14px;

	background: linear-gradient(
		145deg,
		rgba(37, 99, 235, 0.12),
		rgba(124, 58, 237, 0.09)
	);

	text-align: center;
}

.company-event-date-box::after {
	content: "";
	position: absolute;
	right: -18px;
	bottom: -22px;

	width: 60px;
	height: 60px;

	border-radius: 50%;
	background: rgba(79, 70, 229, 0.08);
}

.company-event-month {
	position: relative;
	z-index: 1;

	font-size: 11px;
	font-weight: 800;
	letter-spacing: 1.2px;
	text-transform: uppercase;

	color: #4f46e5;
}

.company-event-day {
	position: relative;
	z-index: 1;

	margin: 4px 0;

	font-size: 31px;
	font-weight: 800;
	line-height: 1;

	color: var(--text-color);
}

.company-event-year {
	position: relative;
	z-index: 1;

	font-size: 11px;
	font-weight: 600;

	color: var(--text-muted);
}


/* Event details */

.company-event-details {
	min-width: 0;
}

.company-event-title-row {
	display: flex;
	align-items: flex-start;
	justify-content: space-between;
	gap: 12px;

	margin-bottom: 9px;
}

.company-event-title {
	margin: 0;

	font-size: 17px;
	font-weight: 750;
	line-height: 1.4;

	color: var(--text-color);
}

.company-event-status {
	flex-shrink: 0;

	display: inline-flex;
	align-items: center;

	padding: 5px 10px;
	border-radius: 20px;

	font-size: 10px;
	font-weight: 800;
	letter-spacing: 0.4px;
	text-transform: uppercase;
}

.event-status-today {
	border: 1px solid rgba(22, 163, 74, 0.2);
	background: rgba(22, 163, 74, 0.1);
	color: #15803d;
}

.event-status-tomorrow {
	border: 1px solid rgba(234, 88, 12, 0.2);
	background: rgba(234, 88, 12, 0.1);
	color: #c2410c;
}

.event-status-upcoming {
	border: 1px solid rgba(79, 70, 229, 0.2);
	background: rgba(79, 70, 229, 0.1);
	color: #4f46e5;
}


/* Metadata */

.company-event-meta {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 8px;

	margin-bottom: 12px;
}

.company-event-meta-item {
	display: inline-flex;
	align-items: center;
	gap: 6px;

	padding: 6px 10px;

	border: 1px solid var(--border-color);
	border-radius: 20px;

	background: var(--control-bg);

	font-size: 11px;
	font-weight: 600;

	color: var(--text-muted);
}

.company-event-meta-item i {
	font-size: 12px;
	color: #4f46e5;
}

.event-days-left {
	border-color: rgba(79, 70, 229, 0.14);
	background: rgba(79, 70, 229, 0.06);
}


/* Description */

.company-event-description {
	padding-top: 12px;
	border-top: 1px dashed var(--border-color);

	font-size: 13px;
	line-height: 1.75;

	color: var(--text-muted);
}

.company-event-description p {
	margin: 0 0 8px;
}

.company-event-description p:last-child {
	margin-bottom: 0;
}

.event-description-empty {
	font-style: italic;
	opacity: 0.8;
}


/* Empty state */

.events-empty-state {
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;

	min-height: 180px;
	padding: 25px;

	text-align: center;
}

.events-empty-icon {
	display: flex;
	align-items: center;
	justify-content: center;

	width: 58px;
	height: 58px;
	margin-bottom: 14px;

	border-radius: 16px;

	background: linear-gradient(
		135deg,
		rgba(37, 99, 235, 0.13),
		rgba(124, 58, 237, 0.1)
	);

	font-size: 23px;
	color: #4f46e5;
}

.events-empty-state h4 {
	margin: 0 0 6px;

	font-size: 16px;
	font-weight: 700;

	color: var(--text-color);
}

.events-empty-state p {
	max-width: 330px;
	margin: 0;

	font-size: 13px;
	line-height: 1.6;

	color: var(--text-muted);
}


/* Dark mode */

[data-theme="dark"] .event-status-today {
	color: #86efac;
}

[data-theme="dark"] .event-status-tomorrow {
	color: #fdba74;
}

[data-theme="dark"] .event-status-upcoming,
[data-theme="dark"] .company-event-month {
	color: #a5b4fc;
}


/* Mobile */

@media (max-width: 650px) {
	.company-event-card {
		grid-template-columns: 65px minmax(0, 1fr);
		gap: 12px;
		padding: 14px;
	}

	.company-event-number {
		display: none;
	}

	.company-event-date-box {
		min-height: 80px;
		padding: 8px 5px;
	}

	.company-event-day {
		font-size: 25px;
	}

	.company-event-title-row {
		flex-direction: column;
		gap: 7px;
	}

	.company-event-title {
		font-size: 15px;
	}

	.company-event-status {
		align-self: flex-start;
	}

	.company-event-meta {
		gap: 6px;
	}

	.company-event-meta-item {
		padding: 5px 8px;
	}
}
